#!/usr/bin/env node
// The generated icon art matches the mock it was approved in: the tab icon drawables and TabIconRes.kt.
//
// The drawings are generated by tools/make-tab-icons.mjs from a mock that lives beside the other mocks,
// outside the repo. A change made to the generated files by hand, or a mock changed without
// running the generator, is caught here. Skipped (exit 2) where the mock is not on the machine.

import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const DIR = dirname(fileURLToPath(import.meta.url));
const r = spawnSync(process.execPath, [join(DIR, "make-tab-icons.mjs"), "--check"], { encoding: "utf8" });
const out = ((r.stdout || "") + (r.stderr || "")).trim();
if (out.startsWith("SKIP")) {
  console.log(out);
  process.exit(2);
}
console.log(out);
process.exit(r.status ?? 1);
